import React, { useState, useEffect } from 'react';
import { CheckCircle, Plus, Trash2 } from 'lucide-react';
import { brandsApi, productsApi, salesApi } from '../api';
import { Page, Card, Input, Select, Btn } from '../components/ui';
import { localDateStr } from '../utils/dates';

// ─── PayNow QR (base64) ──────────────────────────────────────────
// Trimmed placeholder — your actual QR is huge; we keep the original value from the file.
// We'll import it dynamically to keep this readable:
const QR_CODE = "data:image/png;base64,";;

const PAYMENT = {
  uen:     'T23LP0163A',
  name:    'PAWVY LIMITED PARTNERSHIP',
  bank:    'UOB Current Account',
  account: '7723687857',
};

const EMPTY = { brand_id:'', product_id:'', qty:'', unit_price:'', discount_pct:'0', _unit_cost:0 };
const sgd = v => `SGD ${parseFloat(v||0).toFixed(2)}`;
const CHANNEL_OPTIONS = ['Event Sale', 'Direct Online Sale', 'Direct Offline Sale'];

function useIsMobile() {
  const [mobile, setMobile] = useState(window.innerWidth < 768);
  useEffect(() => {
    const h = () => setMobile(window.innerWidth < 768);
    window.addEventListener('resize', h);
    return () => window.removeEventListener('resize', h);
  }, []);
  return mobile;
}

export default function EventSale() {
  const [date,   setDate]  = useState(localDateStr());
  const [channel, setChannel] = useState('Event Sale');
  const [lines,  setLines] = useState([{ ...EMPTY }]);
  const [notes,  setNotes] = useState('');
  const [brands, setBrands]= useState([]);
  const [pbb,    setPbb]   = useState({});
  const [saving, setSaving]= useState(false);
  const [saved,  setSaved] = useState(false);
  const [error,  setError] = useState('');
  const [shippingCharged, setShippingCharged] = useState('');
  const [shippingCost,    setShippingCost]    = useState('');
  const [processingFee,   setProcessingFee]   = useState('');
  const isMobile = useIsMobile();

  useEffect(() => { brandsApi.getAll().then(setBrands); }, []);

  async function ensureProducts(brand_id) {
    if (!brand_id || pbb[brand_id]) return;
    const prods = await productsApi.getAll({ brand_id, active:'true' });
    setPbb(prev => ({ ...prev, [brand_id]: prods }));
  }

  function updateLine(idx, key, val) {
    setLines(prev => {
      const next = prev.map((l,i) => i===idx ? { ...l, [key]:val } : l);
      if (key === 'product_id') {
        const prods = pbb[next[idx].brand_id] || [];
        const prod  = prods.find(p => String(p.id) === String(val));
        if (prod) {
          next[idx].unit_price = prod.price_rrp_sg || prod.price_wholesale_sg || '';
          next[idx]._unit_cost = prod.unit_cost || 0;
        }
      }
      return next;
    });
  }

  const addLine    = ()  => setLines(p => [...p, { ...EMPTY }]);
  const removeLine = (i) => setLines(p => p.filter((_,idx) => idx !== i));

  const calcs = lines.map(l => {
    const qty   = parseFloat(l.qty)          || 0;
    const price = parseFloat(l.unit_price)   || 0;
    const disc  = parseFloat(l.discount_pct) || 0;
    const cost  = parseFloat(l._unit_cost)   || 0;
    const discAmt  = parseFloat((price * disc / 100).toFixed(2));
    const netPrice = parseFloat((price - discAmt).toFixed(2));
    return {
      qty, price, disc, discAmt, netPrice, cost,
      lineTotal:  qty * netPrice,
      // Fix #5: profit = netPrice - cost, NOT subtracting discAmt again
      lineProfit: qty * (netPrice - cost),
    };
  });

  const subtotal  = calcs.reduce((s,c) => s + c.qty * c.price, 0);
  const totalDisc = calcs.reduce((s,c) => s + c.qty * c.discAmt, 0);
  const shipCharged = parseFloat(shippingCharged) || 0;
  const shipCost     = parseFloat(shippingCost) || 0;
  const shipProfit   = shipCharged - shipCost;
  const processingFeeAmt = parseFloat(processingFee) || 0;
  const payable   = subtotal - totalDisc + shipCharged;

  async function handleSave() {
    const valid = lines.filter(l => l.product_id && l.qty && l.unit_price);
    if (!date || valid.length === 0) { setError('Add at least one complete product line.'); return; }
    setSaving(true); setError('');
    try {
      for (const l of valid) {
        const i = lines.indexOf(l);
        const c = calcs[i];
        const isFirst = (i === 0);
        // Fix: save unit_price = full RRP (price before discount), and store the
        // discount as platform_fee_amt — same pattern as B2B sales. This lets the
        // Sales Ledger display "Disc" for Event Sale lines instead of hiding it.
        // Revenue/profit formulas already subtract platform_fee_amt, so the math
        // works out identically to the old netPrice approach.
        // Processing fee is a per-order flat cost, not per-line — only the first
        // line carries it, combined with that line's own item discount amount
        // (both live in the same platform_fee_amt "deductions" field; the notes
        // below document what's included so it's never ambiguous).
        const itemDiscAmt = parseFloat((c.qty * c.discAmt).toFixed(2));
        const lineFeeAmt = isFirst ? parseFloat((itemDiscAmt + processingFeeAmt).toFixed(2)) : itemDiscAmt;
        await salesApi.create({
          date, product_id: l.product_id, partner_id: null,
          channel, market: 'SG',
          qty:              parseInt(l.qty),
          unit_cost:        c.cost,
          unit_price:       c.price,                              // full RRP, not net
          platform_fee_pct: c.disc,                                // discount % for display
          platform_fee_amt: lineFeeAmt,
          shipping_charged: isFirst ? shipCharged : 0,
          shipping_cost:    isFirst ? shipCost    : 0,
          notes: [
            notes || null,
            c.disc > 0 ? `Event discount ${c.disc}% off RRP SGD ${c.price.toFixed(2)}` : null,
            isFirst && shipCharged > 0 ? `Shipping: charged $${shipCharged.toFixed(2)}, cost $${shipCost.toFixed(2)}` : null,
            isFirst && processingFeeAmt > 0 ? `Processing fee: $${processingFeeAmt.toFixed(2)}` : null,
          ].filter(Boolean).join(' | ') || null,
        });
      }
      setSaved(true);
      setTimeout(() => { setSaved(false); setLines([{ ...EMPTY }]); setNotes(''); setShippingCharged(''); setShippingCost(''); setProcessingFee(''); }, 2000);
    } catch(e) { setError(e.message); }
    finally { setSaving(false); }
  }

  return (
    <Page title="EVENT SALE / DIRECT SALE" subtitle="Walk-in customers at events or direct — RRP pricing, unit cost hidden">
      <div style={{display:'flex',flexDirection:'column',gap:12}}>

        <Card>
          <div style={{padding:'12px 16px',display:'flex',alignItems:'center',gap:16,flexWrap:isMobile?'wrap':'nowrap'}}>
            <Input label="Date" type="date" value={date} onChange={e=>setDate(e.target.value)} style={{width:170}}/>
            <Select label="Channel" value={channel} onChange={e=>setChannel(e.target.value)} style={{width:200}}>
              {CHANNEL_OPTIONS.map(c => <option key={c} value={c}>{c}</option>)}
            </Select>
            <div style={{fontSize:11,color:'var(--cream-30)',paddingTop:20}}>
              Price: <strong style={{color:'var(--orange)'}}>RRP</strong>
            </div>
          </div>
        </Card>

        <Card>
          <div style={{padding:'12px 16px 8px',borderBottom:'1px solid var(--border)',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
            <span style={{fontFamily:"'Bebas Neue',sans-serif",fontSize:13,letterSpacing:1,color:'var(--cream)'}}>PRODUCTS</span>
            <Btn size="sm" variant="secondary" onClick={addLine}><Plus size={12}/> Add Product</Btn>
          </div>

          {isMobile ? (
            <div style={{padding:'8px 12px',display:'flex',flexDirection:'column',gap:8}}>
              {lines.map((line, idx) => {
                const prods = pbb[line.brand_id] || [];
                const c = calcs[idx];
                return (
                  <div key={idx} style={{border:'1px solid var(--border)',borderRadius:8,padding:12,background:'rgba(245,242,235,.03)',display:'flex',flexDirection:'column',gap:8}}>
                    <div style={{display:'flex',gap:8}}>
                      <Select value={line.brand_id} onChange={async e=>{updateLine(idx,'brand_id',e.target.value);updateLine(idx,'product_id','');await ensureProducts(e.target.value);}} style={{flex:1}}>
                        <option value="">Brand</option>
                        {brands.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}
                      </Select>
                      <button onClick={()=>removeLine(idx)} disabled={lines.length===1}
                        style={{background:'none',border:'none',color:'rgba(248,113,113,.6)',cursor:'pointer',padding:4,display:'flex',alignItems:'center'}}>
                        <Trash2 size={16}/>
                      </button>
                    </div>
                    <Select value={line.product_id} onChange={e=>updateLine(idx,'product_id',e.target.value)} disabled={!line.brand_id}>
                      <option value="">— Select SKU —</option>
                      {prods.map(p=><option key={p.id} value={p.id}>{p.item_series}{p.variation?' · '+p.variation:''}</option>)}
                    </Select>
                    <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:8}}>
                      <Input label="Qty" type="number" min="1" value={line.qty} onChange={e=>updateLine(idx,'qty',e.target.value)} placeholder="0"/>
                      <Input label="RRP (SGD)" type="number" step="0.01" value={line.unit_price} onChange={e=>updateLine(idx,'unit_price',e.target.value)} placeholder="0.00"/>
                      <Input label="Disc %" type="number" min="0" max="100" value={line.discount_pct} onChange={e=>updateLine(idx,'discount_pct',e.target.value)} placeholder="0"/>
                    </div>
                    {c.lineTotal > 0 && (
                      <div style={{textAlign:'right',fontSize:13,fontWeight:700,color:c.disc>0?'#7fc93e':'var(--cream)'}}>
                        {sgd(c.lineTotal)}
                        {c.disc > 0 && <span style={{fontSize:10,color:'var(--cream-30)',marginLeft:6}}>({c.disc}% off RRP)</span>}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <>
              <div style={{display:'grid',gridTemplateColumns:'1fr 2fr 60px 90px 60px 90px 36px',gap:8,padding:'7px 16px 3px',fontSize:9.5,fontWeight:700,letterSpacing:.8,textTransform:'uppercase',color:'var(--cream-30)'}}>
                <span>Brand</span><span>Product / SKU</span><span>Qty</span><span>RRP Price</span><span>Disc %</span><span style={{textAlign:'right'}}>Total</span><span/>
              </div>
              {lines.map((line, idx) => {
                const prods = pbb[line.brand_id] || [];
                const c = calcs[idx];
                return (
                  <div key={idx} style={{display:'grid',gridTemplateColumns:'1fr 2fr 60px 90px 60px 90px 36px',gap:8,padding:'6px 16px',borderBottom:'1px solid var(--cream-05)'}}>
                    <Select value={line.brand_id} onChange={async e=>{updateLine(idx,'brand_id',e.target.value);updateLine(idx,'product_id','');await ensureProducts(e.target.value);}}>
                      <option value="">Brand</option>
                      {brands.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}
                    </Select>
                    <Select value={line.product_id} onChange={e=>updateLine(idx,'product_id',e.target.value)} disabled={!line.brand_id}>
                      <option value="">— SKU —</option>
                      {prods.map(p=><option key={p.id} value={p.id}>{p.item_series}{p.variation?' · '+p.variation:''}</option>)}
                    </Select>
                    <Input type="number" min="1" value={line.qty} onChange={e=>updateLine(idx,'qty',e.target.value)} placeholder="0"/>
                    <Input type="number" step="0.01" value={line.unit_price} onChange={e=>updateLine(idx,'unit_price',e.target.value)} placeholder="0.00"/>
                    <Input type="number" min="0" max="100" step="1" value={line.discount_pct} onChange={e=>updateLine(idx,'discount_pct',e.target.value)} placeholder="0"/>
                    <div style={{display:'flex',alignItems:'center',justifyContent:'flex-end',fontWeight:700,fontSize:12,color:c.disc>0?'#7fc93e':'var(--cream)'}}>
                      {c.lineTotal > 0 ? sgd(c.lineTotal) : '—'}
                    </div>
                    <button onClick={()=>removeLine(idx)} disabled={lines.length===1}
                      style={{background:'none',border:'none',color:'rgba(248,113,113,.6)',cursor:'pointer',padding:0,display:'flex',alignItems:'center'}}>
                      <Trash2 size={14}/>
                    </button>
                  </div>
                );
              })}
            </>
          )}

          <div style={{padding:'8px 16px'}}>
            <Btn size="sm" variant="ghost" onClick={addLine}><Plus size={12}/> Add another product</Btn>
          </div>
        </Card>

        <Card title="SHIPPING (OPTIONAL)">
          <div style={{padding:'12px 16px',display:'grid',gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr',gap:12}}>
            <Input
              label="Shipping Charged to Customer (SGD)"
              type="number" step="0.01"
              value={shippingCharged}
              onChange={e => setShippingCharged(e.target.value)}
              placeholder="0.00"
            />
            <Input
              label="Actual Shipping Cost (SGD)"
              type="number" step="0.01"
              value={shippingCost}
              onChange={e => setShippingCost(e.target.value)}
              placeholder="0.00"
            />
          </div>
          {shipCharged > 0 && (
            <div style={{padding:'0 16px 12px',fontSize:11,color:'#7fc93e'}}>
              Shipping profit: SGD {shipProfit.toFixed(2)} (charged SGD {shipCharged.toFixed(2)} − cost SGD {shipCost.toFixed(2)})
            </div>
          )}
        </Card>

        <Card title="PROCESSING FEE (OPTIONAL)">
          <div style={{padding:'12px 16px'}}>
            <Input
              label="Processing Fee (SGD)"
              type="number" step="0.01"
              value={processingFee}
              onChange={e => setProcessingFee(e.target.value)}
              placeholder="0.00"
            />
          </div>
        </Card>

        <Card>
          <div style={{padding:14,display:'flex',gap:10,alignItems:'flex-end',flexWrap:isMobile?'wrap':'nowrap'}}>
            <div style={{flex:1,minWidth:isMobile?'100%':undefined}}>
              <Input label="Notes (optional)" value={notes} onChange={e=>setNotes(e.target.value)} placeholder="e.g. partial payment, tester included…"/>
            </div>
            <Btn onClick={handleSave} disabled={saving||saved} size="lg" style={{whiteSpace:'nowrap'}}>
              {saved ? <><CheckCircle size={14}/> Saved!</> : saving ? 'Saving…' : 'Save Sale'}
            </Btn>
          </div>
          {error && <div style={{margin:'0 14px 12px',background:'rgba(248,113,113,.12)',border:'1px solid rgba(248,113,113,.3)',borderRadius:7,padding:'8px 12px',fontSize:12,color:'#f87171'}}>{error}</div>}
        </Card>

        <Card title="ORDER TOTAL">
          <div style={{padding:'14px 16px',display:'flex',flexDirection:'column',gap:9}}>
            {totalDisc > 0 && (
              <>
                <div style={{display:'flex',justifyContent:'space-between'}}>
                  <span style={{fontSize:12,color:'var(--cream-60)'}}>Subtotal (RRP)</span>
                  <span style={{fontSize:12,color:'var(--cream)'}}>{sgd(subtotal)}</span>
                </div>
                <div style={{display:'flex',justifyContent:'space-between'}}>
                  <span style={{fontSize:12,color:'#7fc93e'}}>Discount</span>
                  <span style={{fontSize:12,color:'#7fc93e',fontWeight:700}}>− {sgd(totalDisc)}</span>
                </div>
              </>
            )}
            {shipCharged > 0 && (
              <div style={{display:'flex',justifyContent:'space-between'}}>
                <span style={{fontSize:12,color:'var(--cream-60)'}}>Shipping</span>
                <span style={{fontSize:12,color:'var(--cream)'}}>+ {sgd(shipCharged)}</span>
              </div>
            )}
            {(totalDisc > 0 || shipCharged > 0) && <div style={{height:1,background:'var(--border)'}}/>}
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
              <span style={{fontSize:14,fontWeight:700,color:'var(--cream)'}}>Amount Payable</span>
              <span style={{fontFamily:"'Bebas Neue',sans-serif",fontSize:30,color:'var(--orange)',letterSpacing:1,lineHeight:1}}>
                {sgd(payable)}
              </span>
            </div>
          </div>
        </Card>

        <Card title="PAYMENT">
          <div style={{padding:'14px 16px',display:'flex',flexDirection:'column',alignItems:'center',gap:12}}>
            {QR_CODE && (
              <img src={QR_CODE} alt="PayNow QR"
                style={{width:168,height:168,borderRadius:10,border:'2px solid rgba(245,242,235,.12)',objectFit:'contain'}}/>
            )}
            <div style={{width:'100%',maxWidth:320,margin:'0 auto',display:'flex',flexDirection:'column',gap:7}}>
              {[
                { label:'PayNow UEN', value: PAYMENT.uen },
                { label:'Name',       value: PAYMENT.name },
                { label:'Bank',       value: PAYMENT.bank },
                { label:'Account',    value: PAYMENT.account },
              ].map(row => (
                <div key={row.label} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8}}>
                  <span style={{fontSize:10,color:'var(--cream-30)',fontWeight:600,letterSpacing:.5,textTransform:'uppercase',whiteSpace:'nowrap'}}>{row.label}</span>
                  <span style={{fontSize:11,color:'var(--cream)',fontWeight:600,textAlign:'right'}}>{row.value}</span>
                </div>
              ))}
            </div>
            <div style={{fontSize:10,color:'var(--cream-30)',textAlign:'center',lineHeight:1.7,paddingTop:4,borderTop:'1px solid var(--border)',width:'100%',maxWidth:320,margin:'0 auto'}}>
              Scan QR to pay via PayNow.<br/>Show payment confirmation to staff.
            </div>
          </div>
        </Card>
      </div>
    </Page>
  );
}
